bool AudioLoopbackPrivate::EnableLoopback()
{
    Trace trace("AudioLoopbackPrivate::EnableLoopback");
    karaokeParams_[KaraokeParamType::KARAOKE_PARAM_ENABLE] = 1;
    // Restore legacy dispatch order: send ENABLE first so the nearlink karaoke
    // transition (gated on ENABLE downstream) starts before the other params, as it
    // did when karaokeParams_ was a map<string> iterated in lexicographic order.
    CHECK_AND_RETURN_RET_LOG(
        SetKaraokeParameters(KaraokeParamType::KARAOKE_PARAM_ENABLE, 1), false, "EnableLoopback failed");
    for (auto &param : karaokeParams_) {
        if (param.first == KaraokeParamType::KARAOKE_PARAM_ENABLE) {
            continue;
        }
        auto ret = SetKaraokeParameters(param.first, param.second);
        CHECK_AND_RETURN_RET_LOG(ret, false, "EnableLoopback failed");
    }

    auto timeNow = std::chrono::system_clock::now();

int32_t AudioPolicyServer::SetKaraokeParameters(int32_t deviceType, int32_t paramType, int32_t value, bool &ret)
{
    ret = AudioServerProxy::GetInstance().SetKaraokeParameters(
        static_cast<DeviceType>(deviceType), static_cast<KaraokeParamType>(paramType), value);
    // Only drive the nearlink transition when the downstream AudioServer actually accepted
    // the ENABLE parameter (passed BuildKaraokeParamString validation + HDI dispatch).
    if (ret && static_cast<KaraokeParamType>(paramType) == KaraokeParamType::KARAOKE_PARAM_ENABLE) {
        (void)audioVolumeManager_.StartNearlinkKaraokeTransition(value != 0);
    }
    return SUCCESS;
}

